insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('f60e4c42-c2e3-5735-8058-07628dceeebc', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Ines Cavalcanti' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The shelves are lined with sealed pouches in a pale gradient, no brand names anywhere. It reads like a pharmacy and a grocery had a quiet agreement.', coalesce((select array[image_path] from public.worlds where id='WLD-3021' and image_path is not null), '{}'::text[]), 'seed', '2026-08-02 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('d521eb66-1c58-58fd-bdec-d3d5d77ff611', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Logged it at 02:10 local. The aisle lights pulse very slowly, about one cycle every nine seconds. The register area is unattended.', '{}'::text[], 'seed', '2026-08-04 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('926bcf4d-4ca8-5c95-82dc-ac06cecce1ae', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I''ve checked the stock list on the back wall three times now and the items haven''t changed. Someone is keeping it curated.', '{}'::text[], 'seed', '2026-08-06 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('3fbc954d-1255-5a46-9913-0b52472a4518', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The labels aren''t in any script I can place. The numerals are normal though, prices run in tens.', '{}'::text[], 'seed', '2026-08-08 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('f72263f7-94dc-5a9c-aefe-cc9559220023', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'There''s a hand-painted sign above the dairy case that looks like a folk motif. Odd to find in a place this clean.', '{}'::text[], 'seed', '2026-08-10 12:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('f41f266c-5b65-5d8e-89d7-39348dc42430', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Compared two captures an hour apart. Nothing moved, but the reflection in the freezer glass changed. Someone walked past out of frame.', '{}'::text[], 'seed', '2026-08-12 15:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('28a106a5-4812-5573-8e44-8f4cc374bc3b', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'No produce at all. Everything is packaged and I could hear the cold chain hum, so it is not a mockup.', '{}'::text[], 'seed', '2026-08-14 18:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('46e02de3-2366-52df-b9b0-fccf781b1778', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'What struck me is the quiet. A store with no music, no cart noise. It feels like it is waiting for shoppers rather than empty.', '{}'::text[], 'seed', '2026-08-16 21:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('51976a02-ca4d-5cf8-b26d-bc1d0cde04b8', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'From a distance it looks like our own supermarkets with the colour turned down a notch. Familiar enough to be unsettling.', '{}'::text[], 'seed', '2026-08-18 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('354630a6-6e69-54de-99df-709e36c23512', 'WLD-3021', 'observation', (select id from public.voyager_profiles where display_name='Weile Yang' and id in (select user_id from public.device_access_grants) limit 1), null, 'Confirming the supermarket view. The nutrition-drink wall on the left matches the original submission.', '{}'::text[], 'seed', '2026-08-20 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('cedff775-385c-5f84-b5b5-ce037a4bc142', 'WLD-3021', 'anomaly', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'At 02:40 the lights in aisle three went out for a full minute, then came back one panel at a time from the far end.', '{}'::text[], 'seed', '2026-08-05 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('cc247eee-9b6f-50a3-bb21-1e76425ff669', 'WLD-3021', 'anomaly', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'A shopping basket on the floor wasn''t there in my earlier capture. Nobody on screen.', '{}'::text[], 'seed', '2026-08-07 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('eb953973-6ce8-5eed-8ba4-f76e1a121654', 'WLD-3021', 'anomaly', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I heard what sounded like someone humming through the device speaker. It stopped when I leaned in.', '{}'::text[], 'seed', '2026-08-09 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('0a3de28d-dfc0-584d-b98b-e8bccdbc61e9', 'WLD-3021', 'anomaly', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The prices changed between two visits, all by the same ratio. It felt like inflation done on purpose.', '{}'::text[], 'seed', '2026-08-11 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('7de245c0-d6ba-5649-92e4-c209c8046cc3', 'world', 'WLD-3021', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), 'Ryo Tanaka', 'Does anyone else read this as a place designed for people who stopped needing to cook? The drink wall is the centre of it.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-04 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('55b87f71-0dc4-5f8b-b9a5-1c68129ad348', 'world', 'WLD-3021', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), 'Valentina Cruz', 'I thought the same, but the old-style tins in the corner suggest some people still eat the way we do.', '7de245c0-d6ba-5649-92e4-c209c8046cc3', (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-06 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('bf124290-ff63-5d37-930a-b00ab27cd25c', 'world', 'WLD-3021', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), 'Shen Zhimeng', 'The original post said they''d rather stay in this era because they love food. That tension is the whole point of the place for me.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-08 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('df4cf40e-79ca-5f85-aedd-7831aeed68ac', 'world', 'WLD-3021', (select id from public.voyager_profiles where display_name='Johnaason' and id in (select user_id from public.device_access_grants) limit 1), 'Johnaason', 'Honestly I''d shop here just to find out what ''protein, flavour 4'' tastes like.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-10 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('b27bb173-cf00-567f-8a49-9542ce623821', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Shoreline sediment looks coarse and dark, rocks are rounded like river stones, but there''s no inflow I can see. The water level seems fixed.', coalesce((select array[image_path] from public.worlds where id='PROP-MQM1RW59' and image_path is not null), '{}'::text[]), 'seed', '2026-07-12 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('d3db697c-e10c-5ad3-b201-a21cf29e0b01', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Checked against my archive of lake photos from three continents. The wave period is too regular, almost metronomic.', '{}'::text[], 'seed', '2026-07-14 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('cd6b2de2-78a8-5d3f-9eac-c7c63069c558', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Waves arrive at the same interval every time I look. Whatever is driving it, it is not wind.', '{}'::text[], 'seed', '2026-07-16 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('c3eab7b0-62e9-5570-91c3-3386c9909822', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I kept coming back to the horizon. There is no far shore. The lake just fades into the same grey as the sky.', '{}'::text[], 'seed', '2026-07-18 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('9865859a-f61d-5f9c-9659-17cba43536d1', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The absence of birds bothers me. A shore like this should have gulls. Nothing. Not even a shadow.', '{}'::text[], 'seed', '2026-07-20 12:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('9a4fa7c7-1242-5c74-bae2-05a8e44f6977', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Frame by frame the foam doesn''t dissolve, it just pulls back. It looks like it''s being recalled.', '{}'::text[], 'seed', '2026-07-22 15:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('f1c9a3b0-d30e-5f65-a108-c01a64525ec0', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Ines Cavalcanti' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The colour grade is slightly off, a green cast in the shadows that real lakes don''t have. Beautiful though.', '{}'::text[], 'seed', '2026-07-24 18:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('f48e912b-9cd3-56c9-8a2d-4c807d243f19', 'PROP-MQM1RW59', 'observation', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'No audio from the device by default, but with the volume up there''s a low tone under the waves. Maybe 40 Hz.', '{}'::text[], 'seed', '2026-07-26 21:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('0d6db4d8-101b-519c-acaa-7d73221311dc', 'PROP-MQM1RW59', 'anomaly', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The tone rose by about a half step while I was watching. It dropped again after a minute.', '{}'::text[], 'seed', '2026-07-15 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('11cdb172-4865-5be5-bc5f-5b44d40ed644', 'PROP-MQM1RW59', 'anomaly', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'A rock near the foreground changed position between two captures about ten minutes apart.', '{}'::text[], 'seed', '2026-07-17 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('022d128f-0483-5be5-80e5-f9be82fecac6', 'PROP-MQM1RW59', 'anomaly', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Footprints appeared on the sand. A single set leading toward the water, none coming back.', '{}'::text[], 'seed', '2026-07-19 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('346f9bc1-64a2-52b3-af8f-c66cfa544622', 'PROP-MQM1RW59', 'anomaly', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I felt watched for the whole session. I know that''s not data, but I''m writing it down.', '{}'::text[], 'seed', '2026-07-21 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('0de42dbb-26b0-58ad-aa1a-ab4f9751ad12', 'PROP-MQM1RW59', 'anomaly', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The sky brightened as though someone had opened a door behind the camera.', '{}'::text[], 'seed', '2026-07-23 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('41955d6e-0eee-5041-9574-cf313f35c01c', 'world', 'PROP-MQM1RW59', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), 'Saoirse Flanagan', 'The ''off'' feeling in the description is real. It took me three visits to name it: nothing here has a smell.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-14 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('cd7ecbf2-ca3c-5fb0-8c6d-83c104a804e0', 'world', 'PROP-MQM1RW59', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), 'Amara Okafor', 'Interesting that you say smell. Water like that usually announces itself, even on a screen. I''d expect the same.', '41955d6e-0eee-5041-9574-cf313f35c01c', (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-16 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('c5d06f30-d2df-5274-85aa-56320d5e4b57', 'world', 'PROP-MQM1RW59', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), 'Ryo Tanaka', 'Maybe the lake is the only part of this world that looks like ours, and that''s exactly what makes it uncanny.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-18 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('90fde37d-40e9-5664-b10c-446c0f3e708b', 'world', 'PROP-MQM1RW59', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), 'Shen Zhimeng', 'Has anyone lined up the wave interval against the footprints? I suspect they''re connected.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-20 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('900241fc-b6ee-5cd2-a776-a77665f1ddef', 'PROP-MQHICUD6', 'observation', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Control panels are all physical: toggles, a brass-rimmed gauge, even a hand-lettered label strip. This ship was built to be repaired.', coalesce((select array[image_path] from public.worlds where id='PROP-MQHICUD6' and image_path is not null), '{}'::text[]), 'seed', '2026-07-18 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('e73ff597-526d-516c-90b7-4563d5d5e4e6', 'PROP-MQHICUD6', 'observation', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The viewport shows a star field that doesn''t rotate. Either the ship is holding station or the window is a display.', '{}'::text[], 'seed', '2026-07-20 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('2868c9a9-0045-56d3-9a6d-b06d0c97cfab', 'PROP-MQHICUD6', 'observation', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I like that the dials have small scratches around the knobs, the kind you get from thousands of turns.', '{}'::text[], 'seed', '2026-07-22 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('5ba12428-e418-5a6e-97cd-03568f825ff1', 'PROP-MQHICUD6', 'observation', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Warm light inside, cold light outside. The contrast does most of the work.', '{}'::text[], 'seed', '2026-07-24 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('609d8baa-3c13-57c3-ad94-62879a3ae1a0', 'PROP-MQHICUD6', 'observation', (select id from public.voyager_profiles where display_name='Johnaason' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Felt strangely at home. Like an old camper van, just parked in the void.', '{}'::text[], 'seed', '2026-07-26 12:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('e6b9967c-860f-5e43-93a4-aa3ca45c5fcd', 'PROP-MQHICUD6', 'observation', (select id from public.voyager_profiles where display_name='Ines Cavalcanti' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The upholstery is mustard and rust, very late seventies. Someone chose that on purpose.', '{}'::text[], 'seed', '2026-07-28 15:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('cf185b0f-bc2a-5d2a-a935-386ba5ec5021', 'PROP-MQHICUD6', 'observation', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The hum on the audio is steady at around 60 Hz, with a flutter every few minutes that looks like a fan spinning up.', '{}'::text[], 'seed', '2026-07-30 18:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('78d81d87-87da-5955-b914-08252bad6b6b', 'PROP-MQHICUD6', 'anomaly', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The dust motes in the cabin drifted upward, against what I''d expect from any gravity I know.', '{}'::text[], 'seed', '2026-07-21 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('e80e28ae-be5b-5dac-8bd7-a999af51a68b', 'PROP-MQHICUD6', 'anomaly', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'At 22:05 one of the gauges swung to the far end and back with nobody touching it.', '{}'::text[], 'seed', '2026-07-23 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('6ca81200-dd2b-508a-a3b9-cf8c22db3a20', 'PROP-MQHICUD6', 'anomaly', (select id from public.voyager_profiles where display_name='Johnaason' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I swear a cup on the console slid an inch by itself.', '{}'::text[], 'seed', '2026-07-25 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('1f2baf23-a0c7-5255-afce-5186bb4088c1', 'world', 'PROP-MQHICUD6', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), 'Luke Brandner', 'What I appreciate is that nothing in here is trying to impress you. It''s a working vessel.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-20 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('f7ab9794-ffec-54ec-93c1-2ac8f21ff310', 'world', 'PROP-MQHICUD6', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), 'Maren Solberg', 'The window may be the real anomaly. I can''t find any parallax in the stars.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-22 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('844b3ae0-f2bd-568e-a744-d8f9df3bc963', 'world', 'PROP-MQHICUD6', (select id from public.voyager_profiles where display_name='Johnaason' and id in (select user_id from public.device_access_grants) limit 1), 'Johnaason', 'Whoever lives here has been alone for a very long time, and they''ve decorated for it.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-24 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('662f3c3a-d650-5b72-bc72-37a1ad1e9a30', 'world', 'PROP-MQHICUD6', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), 'Page Chen', 'I''d love to see the other side of the cockpit. The camera never turns.', 'f7ab9794-ffec-54ec-93c1-2ac8f21ff310', (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-26 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('a933f49b-f90f-562a-a473-743dd53d4f6a', 'PROP-MQGFX02N', 'observation', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Carriage after carriage with a different purpose: a reading car, a greenhouse, one that seems to be a kitchen. It really is a village on wheels.', coalesce((select array[image_path] from public.worlds where id='PROP-MQGFX02N' and image_path is not null), '{}'::text[]), 'seed', '2026-07-25 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('9b93ed1d-7152-5851-9cdf-624ad7e97b3f', 'PROP-MQGFX02N', 'observation', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The lettering on the carriage doors mixes two scripts. I can read the numbers, nothing else.', '{}'::text[], 'seed', '2026-07-27 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('680ba30c-1e35-5888-8d2a-b9c98068e651', 'PROP-MQGFX02N', 'observation', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Steam rises from somewhere under the floor even in the interior shots. Cosy, but not dangerous.', '{}'::text[], 'seed', '2026-07-29 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('c1038eb9-55b0-5870-9710-54e86bd2f254', 'PROP-MQGFX02N', 'observation', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The greenhouse car has real plants. I can see leaf damage from the vibration.', '{}'::text[], 'seed', '2026-07-31 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('e9fd1616-78e5-5607-9904-3dd497b51e70', 'PROP-MQGFX02N', 'observation', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The girl in the corridor looks completely unbothered, as though the train has always been moving.', '{}'::text[], 'seed', '2026-08-02 12:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('bc590864-d7fd-54bf-91a2-ff71ca7e3c5e', 'PROP-MQGFX02N', 'observation', (select id from public.voyager_profiles where display_name='Ines Cavalcanti' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Lovely use of colour. Every carriage has its own palette but they all belong to one family.', '{}'::text[], 'seed', '2026-08-04 15:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('2f8d5bf4-4808-586b-bb11-56f6055ba0bc', 'PROP-MQGFX02N', 'anomaly', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The corridor between the second and third car is longer on the way back than on the way there.', '{}'::text[], 'seed', '2026-07-28 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('4f54afed-a008-5018-b50c-6cedffd04af6', 'PROP-MQGFX02N', 'anomaly', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The scenery repeated, same hill and same lone tree, three times in ten minutes.', '{}'::text[], 'seed', '2026-07-30 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('d03cf326-2203-5b6d-b984-0a86459b9f08', 'PROP-MQGFX02N', 'anomaly', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The conductor''s whistle sounded twice, but there is no conductor visible in any capture.', '{}'::text[], 'seed', '2026-08-01 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('9283d2bd-3611-5520-8430-023a43bdaddd', 'world', 'PROP-MQGFX02N', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), 'Saoirse Flanagan', 'It reminds me of old tales where a journey is also a place. People don''t go anywhere, they live in between.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-27 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('3428539d-564e-5da2-9635-d1ca4822cca1', 'world', 'PROP-MQGFX02N', (select id from public.voyager_profiles where display_name='Ines Cavalcanti' and id in (select user_id from public.device_access_grants) limit 1), 'Ines Cavalcanti', 'I''d ride it just for the greenhouse car.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-29 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('b39fbc8f-9d44-5fa4-bf80-422c9cf8d4c7', 'world', 'PROP-MQGFX02N', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), 'Tariq Osei', 'I counted eleven carriages in one capture and nine in another. Counting on a moving train is hard, but still.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-07-31 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('d8de243d-8b4c-580e-ba94-742f2ece2b48', 'PROP-MQFRHU0V', 'observation', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'White sand, strong overhead sun, and a haze that bends everything near the ground. A standard desert opening, and then the shapes arrive.', coalesce((select array[image_path] from public.worlds where id='PROP-MQFRHU0V' and image_path is not null), '{}'::text[]), 'seed', '2026-08-05 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('f1cb3f75-1064-5bd9-a707-4b88b87d209f', 'PROP-MQFRHU0V', 'observation', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The heat shimmer here is persistent. In a real desert it breaks up at dusk. This didn''t, even as the light shifted.', '{}'::text[], 'seed', '2026-08-07 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('0c9658a5-1e66-5250-ae6a-f65f31c47896', 'PROP-MQFRHU0V', 'observation', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The floating geometric forms keep a constant distance from the camera. They seem aware of it.', '{}'::text[], 'seed', '2026-08-09 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('dd81a1a9-8f32-5a11-b695-3bef46319511', 'PROP-MQFRHU0V', 'observation', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Camel-like animals, but the proportions are wrong, the necks too long. They move in a loose line.', '{}'::text[], 'seed', '2026-08-11 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('df4d570f-69b9-5e2f-84d6-d24fb2cfd144', 'PROP-MQFRHU0V', 'observation', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The colours don''t map to anything. The sky sometimes holds a band I can only describe as ''a colour between green and a sound''.', '{}'::text[], 'seed', '2026-08-13 12:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('5266646e-3c23-5614-9e19-325d685fee1f', 'PROP-MQFRHU0V', 'anomaly', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The temperature readout on my station jumped six degrees the moment one of the geometric forms passed.', '{}'::text[], 'seed', '2026-08-08 09:00:00+00') on conflict (id) do nothing;
