insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('ede59191-130c-5667-8934-6a4331ef64c8', 'PROP-MQFRHU0V', 'anomaly', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'For about thirty seconds all the animals turned and faced the same direction.', '{}'::text[], 'seed', '2026-08-12 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('4368d143-64cb-5e61-98c8-f62680ce6924', 'world', 'PROP-MQFRHU0V', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), 'Maren Solberg', '''Ashen Horizon'' is a good name. The horizon is the only thing that stays still.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-07 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('d8ae6b59-ac3e-54cf-8235-12112734ce20', 'world', 'PROP-MQFRHU0V', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), 'Amara Okafor', 'The sand is almost certainly gypsum-like. It stays white under that sun. That grounds it for me.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-09 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('93ffc3ac-93ae-5869-a9e6-00a86bad7db8', 'world', 'PROP-MQFRHU0V', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), 'Tariq Osei', 'Is Zorch the same world as in the other reports? The description matches.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-11 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('cf252e8a-1f33-5a7e-8241-7e23b6753ac5', 'WLD-111', 'observation', (select id from public.voyager_profiles where display_name='Johnaason' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I just wanted to lie down on the beach and I did, in my head. The waves and the warm light work like a lullaby.', coalesce((select array[image_path] from public.worlds where id='WLD-111' and image_path is not null), '{}'::text[]), 'seed', '2026-08-12 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('a19bf2fd-3d3a-559a-be62-896b0c25832e', 'WLD-111', 'observation', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The office building is visible behind the beach, all glass. It is the least restful thing in the frame and that''s the joke.', '{}'::text[], 'seed', '2026-08-14 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('40f269ca-1431-5f6a-b91e-b065d3a85786', 'WLD-111', 'observation', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'No one is on the sand. It feels like a place that has been left for you.', '{}'::text[], 'seed', '2026-08-16 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('77cc4e4f-2ddd-5d2a-946e-6cdb0cfb1714', 'WLD-111', 'observation', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I turned the volume up: a very low surf and a distant keyboard. Both comfortable.', '{}'::text[], 'seed', '2026-08-18 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('fb3f6048-f5dd-5bda-a0da-295af18a2811', 'WLD-111', 'anomaly', (select id from public.voyager_profiles where display_name='Johnaason' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Watched the tide line for forty minutes and it never moved. I fell asleep anyway.', '{}'::text[], 'seed', '2026-08-15 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('2c927632-452e-5e86-a032-2550a99ecf7a', 'world', 'WLD-111', (select id from public.voyager_profiles where display_name='Johnaason' and id in (select user_id from public.device_access_grants) limit 1), 'Johnaason', 'Everyone who finds this one wants to quit their job. That might be the anomaly.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-14 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('cf390643-a696-5a65-bdbc-fe71b72f9112', 'world', 'WLD-111', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), 'Valentina Cruz', 'It''s the ordinariness that works. Nothing strange happens, and that''s the strange part.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-16 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('89128ab8-10d3-519d-a4df-b532b57c15e2', 'world', 'WLD-111', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), 'Ryo Tanaka', 'Rest as a place rather than a state. I like that.', '2c927632-452e-5e86-a032-2550a99ecf7a', (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-18 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('349bd25b-429d-56ff-8d93-49ee4892d565', 'PROP-MQCF6EDL', 'observation', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'A being experiencing birth to death at once. The scene is shot as stillness with a slight, constant flicker, as though many moments were laid on top of each other.', coalesce((select array[image_path] from public.worlds where id='PROP-MQCF6EDL' and image_path is not null), '{}'::text[]), 'seed', '2026-07-30 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('e1b7b2ac-efa7-5bf9-91df-83cc825d4ec5', 'PROP-MQCF6EDL', 'observation', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The flicker rate is exactly 24 per second. Intentional framing, or a property of the signal?', '{}'::text[], 'seed', '2026-08-01 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('c9c6371f-8cae-51e2-a87e-5cb738c5fc3a', 'PROP-MQCF6EDL', 'observation', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Every shadow in the frame points a different way. If you accept that all hours exist at once, that makes sense.', '{}'::text[], 'seed', '2026-08-03 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('c683d383-a8a1-5eb2-b641-9ef4232d4a9c', 'PROP-MQCF6EDL', 'observation', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I compared the two ends of the capture. A candle burns down and is whole again in the same shot.', '{}'::text[], 'seed', '2026-08-05 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('280daf48-6506-5819-b10a-a29479314335', 'PROP-MQCF6EDL', 'anomaly', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'I watched a figure age in the doorway across a single exhale.', '{}'::text[], 'seed', '2026-08-02 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('b89d5c7c-a578-5562-90a1-5dbc07abaff2', 'PROP-MQCF6EDL', 'anomaly', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The device clock and the world''s clock disagreed by eleven minutes after the session. Mine was behind.', '{}'::text[], 'seed', '2026-08-04 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('30cef79c-da60-51bc-8e73-f3a56287f557', 'world', 'PROP-MQCF6EDL', (select id from public.voyager_profiles where display_name='Ryo Tanaka' and id in (select user_id from public.device_access_grants) limit 1), 'Ryo Tanaka', 'The unsettling thing is how calm it is. Knowing the end doesn''t seem to hurt them.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-01 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('e4c910d5-ec94-58a1-a39b-d136672d4a37', 'world', 'PROP-MQCF6EDL', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), 'Maren Solberg', 'I''d want to test whether my own timestamps drift again before drawing anything from it.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-03 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('e59be610-4b17-586a-9b39-3b6042fbd7b6', 'world', 'PROP-MQCF6EDL', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), 'Page Chen', 'A place where decisions can''t be regretted, because they aren''t in the past.', '30cef79c-da60-51bc-8e73-f3a56287f557', (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-05 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('56cf510b-6b94-5235-bc34-dde776212f4e', 'PROP-MQOQ5OLY', 'observation', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The brush in the foreground is dense, and in the middle there is a shape that holds still when everything else sways. It stays in the frame after the camera moves.', coalesce((select array[image_path] from public.worlds where id='PROP-MQOQ5OLY' and image_path is not null), '{}'::text[]), 'seed', '2026-08-18 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('45a64b34-a222-5fe7-ac34-d40e1605b354', 'PROP-MQOQ5OLY', 'observation', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Russian River riparian vegetation, blackberry brambles, I know the species. Nothing in that shape fits an animal I''d expect there.', '{}'::text[], 'seed', '2026-08-20 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('8144de60-74da-50c1-8594-1993af96f480', 'PROP-MQOQ5OLY', 'observation', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Zoomed to the maximum. The ''eyes'' are two points of light, spaced about the width of a human head, at a distance that matches the reported fifteen feet.', '{}'::text[], 'seed', '2026-08-22 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('0d9d9127-3cc8-5ea0-a614-8b74c8687da6', 'PROP-MQOQ5OLY', 'observation', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'My grandmother used to say there was something behind everything. This looks like that, but patient.', '{}'::text[], 'seed', '2026-08-24 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('595fb3ab-175e-5940-b12b-554350ee52bc', 'PROP-MQOQ5OLY', 'anomaly', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The birdsong around the brambles stopped when the shape appeared and resumed when it left the frame.', '{}'::text[], 'seed', '2026-08-21 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('248ab1a4-320c-50b0-933b-caa78af86f84', 'PROP-MQOQ5OLY', 'anomaly', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'A second pair of points showed up to the left for about four seconds.', '{}'::text[], 'seed', '2026-08-23 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('f73055ce-6022-5618-a5ab-e5cf82732a9e', 'world', 'PROP-MQOQ5OLY', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), 'Amara Okafor', 'As someone who spends time in that kind of habitat: animals look at you, and this looks at the camera.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-20 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('173e1a07-9dd2-5c28-843b-4061483b4c2a', 'world', 'PROP-MQOQ5OLY', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), 'Saoirse Flanagan', '''Feels right'' in the description is the part I trust most. It doesn''t read like it was made up.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-22 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('3e343b1f-c2bf-5460-a781-31ae7fe9d4c1', 'world', 'PROP-MQOQ5OLY', (select id from public.voyager_profiles where display_name='Shen Zhimeng' and id in (select user_id from public.device_access_grants) limit 1), 'Shen Zhimeng', 'I''m not sure it belongs here either, but it''s the first report in a while I''ve watched twice.', 'f73055ce-6022-5618-a5ab-e5cf82732a9e', (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-24 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('fc1df478-4676-5d98-a3b7-2fe5933a856d', 'WLD-199', 'observation', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The screen is smeared with something green and wet. Through it you can see a lit hearth and a very old wooden room.', coalesce((select array[image_path] from public.worlds where id='WLD-199' and image_path is not null), '{}'::text[]), 'seed', '2026-08-22 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('bc2a8183-bd51-5424-8754-09ec33a884a7', 'WLD-199', 'observation', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The crackle of the firewood is clear and warm. The muck is the first thing you notice, the hearth is the second, and it takes over.', '{}'::text[], 'seed', '2026-08-24 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('38186acd-0f79-5422-8d8b-fd2e395e4bc0', 'WLD-199', 'observation', (select id from public.voyager_profiles where display_name='Ines Cavalcanti' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The textures are glorious. It should be disgusting and it''s actually tender.', '{}'::text[], 'seed', '2026-08-26 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('d8b89386-50db-5c6d-a046-ac5ed4cb9a65', 'WLD-199', 'observation', (select id from public.voyager_profiles where display_name='Amara Okafor' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Someone lives here alone and keeps the fire going. There are no footprints in the ash, so it''s maintained by one set of hands.', '{}'::text[], 'seed', '2026-08-28 09:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('bdf5bbb3-3614-52b7-9ad2-3d3113ae53db', 'WLD-199', 'anomaly', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The slime rippled in time with the crackle, as if it were listening.', '{}'::text[], 'seed', '2026-08-25 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('623315f5-3bb7-5b2a-a1cf-5345e1bd1ee8', 'world', 'WLD-199', (select id from public.voyager_profiles where display_name='Valentina Cruz' and id in (select user_id from public.device_access_grants) limit 1), 'Valentina Cruz', 'It''s the quiet kind of lonely. A house that has been staying in itself.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-24 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('63318d0d-d087-5f79-8445-31cbf18742da', 'world', 'WLD-199', (select id from public.voyager_profiles where display_name='Ines Cavalcanti' and id in (select user_id from public.device_access_grants) limit 1), 'Ines Cavalcanti', 'Healing is the right word. I came to laugh and stayed for the fire.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-26 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('577d41c7-ca9e-5aad-b449-d5ce0aeb92ca', 'WLD-999', 'observation', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'A small bright thing at the edge of the frame, faster than a bird, with a hover pattern that looks deliberate. I''m not comfortable calling it a pixie, but I understand why.', coalesce((select array[image_path] from public.worlds where id='WLD-999' and image_path is not null), '{}'::text[]), 'seed', '2026-08-27 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('d2226550-2463-57d6-a124-ac0a1e9d48f2', 'WLD-999', 'observation', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Wishes in folklore usually come with a cost. The thing in this capture is very careful not to come close.', '{}'::text[], 'seed', '2026-08-29 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('94abf767-f38a-5945-8b8f-fec453ddb72e', 'WLD-999', 'observation', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Captured it three times across two sessions. Same trajectory, same small loop.', '{}'::text[], 'seed', '2026-08-31 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('bd747a1d-290c-5316-9b4a-cc2f3ceb913f', 'WLD-999', 'anomaly', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'After the session I found myself remembering a summer from when I was eight, in detail I hadn''t had for years.', '{}'::text[], 'seed', '2026-08-30 09:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('f2cb8036-6f2f-5f54-b8df-200d54480b03', 'world', 'WLD-999', (select id from public.voyager_profiles where display_name='Saoirse Flanagan' and id in (select user_id from public.device_access_grants) limit 1), 'Saoirse Flanagan', 'The memory part is the real offer, isn''t it? Not flight, just getting back.', null, (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-29 14:00:00+00') on conflict (id) do nothing;
insert into public.comments (id, subject_type, subject_id, author_id, author_name, body, parent_id, posted_by_id, is_visible, image_paths, created_at) values ('df8f331e-a111-5376-bcde-ea6b70bc1abe', 'world', 'WLD-999', (select id from public.voyager_profiles where display_name='Maren Solberg' and id in (select user_id from public.device_access_grants) limit 1), 'Maren Solberg', 'Interesting that several of us report something about childhood. It could be the framing of the original submission.', 'f2cb8036-6f2f-5f54-b8df-200d54480b03', (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), true, '{}', '2026-08-31 14:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('ec1e3291-cd0e-5208-b74d-671e8c959988', 'PROP-MQDI6QYJ', 'observation', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Square-set timbers and a rail line running into the dark. The timber work matches the 1940s mines in that region.', coalesce((select array[image_path] from public.worlds where id='PROP-MQDI6QYJ' and image_path is not null), '{}'::text[]), 'seed', '2026-08-08 00:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('ff9f7e19-32c9-53c3-8234-2cd7d923f675', 'PROP-MQDI6QYJ', 'observation', (select id from public.voyager_profiles where display_name='Page Chen' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'The tunnel is lit by something that isn''t a lamp. It brightens as you go in and there is no source.', '{}'::text[], 'seed', '2026-08-10 03:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('e0e1350e-27cb-5d58-be8f-0ce118be312a', 'PROP-MQDI6QYJ', 'observation', (select id from public.voyager_profiles where display_name='Tariq Osei' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'Mileage markers on the wall: 0.1, 0.2, 0.3. They keep going well past what the original mine could have had.', '{}'::text[], 'seed', '2026-08-12 06:00:00+00') on conflict (id) do nothing;
insert into public.world_reports (id, world_id, kind, author_id, posted_by_id, body, image_urls, source, created_at) values ('61e55001-31b1-54c3-a8aa-e67b340b3021', 'PROP-MQDI6QYJ', 'anomaly', (select id from public.voyager_profiles where display_name='Luke Brandner' and id in (select user_id from public.device_access_grants) limit 1), (select id from public.voyager_profiles where display_name='Weile Yang' and account_kind='human' and role='architect' limit 1), 'A second, newer set of rails appears halfway down, same gauge but a different material.', '{}'::text[], 'seed', '2026-08-11 09:00:00+00') on conflict (id) do nothing;
